def add_sheet(name, text, widths, table_name):
    ws = wb.create_sheet(name)
    rows = parse_tsv(text)
    count = len(rows[0])
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=count)
    ws.cell(1, 1, name).font = Font(name="Calibri", size=18, bold=True, color="FFFFFF")
    ws.cell(1, 1).fill = PatternFill("solid", fgColor=NAVY)
    ws.row_dimensions[1].height = 32
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=count)
    ws.cell(2, 1, "Снимок предыдущего анализа • 10.09.2026 • Последующие исправления не переаудированы")
    ws.cell(2, 1).font = Font(name="Calibri", size=11, italic=True, color=GREY)
    ws.row_dimensions[2].height = 25
    ws.cell(3, 1, "К оглавлению").hyperlink = "#'Об отчёте'!A1"
    ws.cell(3, 1).style = "Hyperlink"
    for r, values in enumerate(rows, 5):
        for c, value in enumerate(values, 1):
            cell = ws.cell(r, c, int(value) if c == 1 and value.isdigit() else value)
            cell.font = Font(name="Calibri", size=11, color="203449", bold=(r == 5))
            cell.alignment = Alignment(vertical="top", wrap_text=True)
            if r == 5:
                cell.fill = PatternFill("solid", fgColor=NAVY)
                cell.font = Font(name="Calibri", size=11, color="FFFFFF", bold=True)
            elif r % 2 == 0:
                cell.fill = PatternFill("solid", fgColor="F0F5FA")
            if value == "Критический":
                cell.fill = PatternFill("solid", fgColor="FCE5E5")
                cell.font = Font(name="Calibri", size=11, color="A62626", bold=True)
        lines = max(
            sum(max(1, len(textwrap.wrap(part, width=max(5, int(widths[c] * .87))))) for part in value.split("\n"))
            for c, value in enumerate(values)
        )
        ws.row_dimensions[r].height = max(42 if r == 5 else 58, min(390, lines * 15 + 14))
    for c, width in enumerate(widths, 1):
        ws.column_dimensions[get_column_letter(c)].width = width
    table = Table(displayName=table_name, ref=f"A5:{get_column_letter(count)}{4 + len(rows)}")
    table.tableStyleInfo = TableStyleInfo(name="TableStyleMedium2", showRowStripes=True)
    ws.add_table(table)
    ws.freeze_panes = "C6" if rows[0][0] == "№" else "B6"
    ws.sheet_view.showGridLines = False
    ws.sheet_view.zoomScale = 80
    ws.print_title_rows = "1:5"
    ws.print_options.horizontalCentered = True
    ws.page_setup.orientation = "landscape"
    ws.page_setup.paperSize = ws.PAPERSIZE_A3
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.print_area = f"A1:{get_column_letter(count)}{ws.max_row}"
    ws.oddFooter.center.text = "Страница &P из &N"
    return len(rows) - 1


